	sg_miter_start(&host->sg_miter, data->sg, data->sg_len,
		       SG_MITER_FROM_SG);

	host->wait_for = MMCIF_WAIT_FOR_MWRITE;

	sh_mmcif_bitset(host, MMCIF_CE_INT_MASK, MASK_MBUFWEN);
}

